  const ms = romaMs(a, me, g, o, mi);
  return { chiave: `${a}-${due(me)}-${due(g)} ${due(o)}:${due(mi)}`, ms };
};
const idDaLink = (voce) => {
  const t = testo(voce);
  const m = t.match(/\/d\/([A-Za-z0-9_-]{10,})/) || t.match(/[?&]id=([A-Za-z0-9_-]{10,})/);
  if (m) return m[1];
  if (/^[A-Za-z0-9_-]{10,}$/.test(t)) return t;
  return '';
};
const fileDellaRiga = (r) => [r.media, r.copertina].flatMap((c) => testo(c).split('|')).map(idDaLink).filter(Boolean);
// impronta breve di un testo (djb2), per riconoscere lo stesso problema tra un giro e l'altro
const impronta = (s) => { let h = 5381; for (const ch of String(s ?? '')) h = ((h * 33) ^ ch.codePointAt(0)) >>> 0; return h.toString(16); };
const VIVI = ['idea', 'bozza', 'da_scrivere', 'da_approvare', 'approvato'];
const TIPI = ['post', 'carosello', 'reel', 'storia'];
const COLONNE_TESTO = ['brief', 'didascalia', 'primo_commento'];

// Guarda le righe vive del Calendario e la scheda Clienti, e decide per ogni problema cosa fare:
// auto (correzione da sola), pausa (correzione o solo stato → da_approvare), proposta (pulsanti su Telegram), avviso (solo riepilogo).
// Non scrive niente: esce con un item solo, l'elenco dei problemi. Le scritture le fanno i rami dopo, rileggendo il foglio
// e scrivendo per numero di riga (row_number), dopo aver ricontrollato che l'id sia ancora quello.
const cfg = $('Config').first().json;
const orario = $('Ogni ora').isExecuted;
const adesso = Date.now();
const ORA = 3600000;
const oreVicina = Number(cfg.ORE_VICINA_USCITA) || 24;
const oreGiro = Number(cfg.ORE_GIRO_ORARIO) || 3;
const giorniAvanti = Number(cfg.GIORNI_AVANTI) || 60;
const oreAttesa = Number(cfg.ORE_ATTESA_RISPOSTA) || 24;
const maxProposte = Math.max(0, Number(cfg.MAX_PROPOSTE) || 15);

// --- prezzi: «€ 12», «12,50 €», «13 euro», «1.500 €», «10-12 €», con le parole che li accompagnano ---
const NUM = '(?:\\d{1,3}(?:\\.\\d{3})+(?:,\\d{1,2})?|\\d{1,4}(?:[.,]\\d{1,2})?)';
const INTERVALLO = `${NUM}(?:[ \\t\\u00a0\\u202f]*[-–][ \\t\\u00a0\\u202f]*${NUM})?`;
const SOLO_PREZZO = `(?:€[ \\t\\u00a0\\u202f]*${INTERVALLO}|(?<![\\d.,])${INTERVALLO}[ \\t\\u00a0\\u202f]*(?:€|euro\\b|eur\\b))`;
const PREZZO = new RegExp(SOLO_PREZZO, 'i');
const PREZZO_CON_PAROLE = () => new RegExp(`[ \\t\\u00a0\\u202f]*(?:\\b(?:a partire da|a soli|a solo|a|da|solo|soli)[ \\t\\u00a0\\u202f]+)?${SOLO_PREZZO}`, 'gi');
const LETTERA = /[A-Za-zÀ-ÖØ-öø-ÿ]/;
// Toglie i prezzi solo dove la frase resta intera: prima del prezzo niente «:», «-», «/» o cifre, dopo il prezzo
// fine riga o punteggiatura. Altrimenti (es. «Spendi 20€ e ricevi…», «Margherita: 8 €, Diavola: 9 €») è «sospetto»
// e non si tocca: lo sistema una persona. Le pulizie (spazi, parentesi vuote) si fanno solo nel punto del taglio.
const togliPrezzi = (t) => {
  const s = String(t);
  let out = '';
  let ultimo = 0;
  let sospetto = false;
  const tolti = [];
  for (const m of s.matchAll(PREZZO_CON_PAROLE())) {
    const inizio = m.index;
    const fine = inizio + m[0].length;
    const prima = s.slice(0, inizio).replace(/[ \t\u00a0\u202f]+$/, '');
    const dopo = s.slice(fine);
    const cPrima = prima.slice(-1);
    const cDopo = Array.from(dopo.replace(/^[ \t\u00a0\u202f]*/, ''))[0] || '';
    if (/[:\-–—/·=+×,\d]/.test(cPrima)) sospetto = true;
    // una parola appesa prima del prezzo («ricco e a 11 euro», «menu di 20 €»): togliendolo la frase resterebbe monca
    const ultimaParola = (prima.match(/([A-Za-zÀ-ÖØ-öø-ÿ']+)$/) || ['', ''])[1].toLowerCase();
    if (/^(?:e|ed|o|od|di|del|della|dei|delle|con|per|in|su|tra|fra|che|il|lo|la|i|gli|le|un|uno|una|al|alla|ai|alle)$/.test(ultimaParola)) sospetto = true;
    if (/[\p{L}\d]/u.test(cDopo)) sospetto = true;
    if (/^[^ \t\u00a0\u202f]/.test(m[0]) && LETTERA.test(s.slice(inizio - 1, inizio))) sospetto = true; // «a8€»
    if (/\d[ \t\u00a0\u202f]*[-–][ \t\u00a0\u202f]*\d/.test(m[0])) sospetto = true; // «12-15 €» può essere un orario
    tolti.push(m[0].trim());
    out += s.slice(ultimo, inizio);
    ultimo = fine;
    // spazi prima della punteggiatura che segue, e parentesi rimaste vuote
    const resto = s.slice(ultimo);
    const sp = resto.match(/^[ \t\u00a0\u202f]+(?=[.,;!?)…])/);
    if (sp) ultimo += sp[0].length;
    if (/\([ \t\u00a0\u202f]*$/.test(out) && /^[ \t\u00a0\u202f]*\)/.test(s.slice(ultimo))) {
      out = out.replace(/[ \t\u00a0\u202f]*\([ \t\u00a0\u202f]*$/, '');
      ultimo += s.slice(ultimo).match(/^[ \t\u00a0\u202f]*\)/)[0].length;
    }
  }
  out += s.slice(ultimo);
  out = out.replace(/[ \t\u00a0\u202f]+$/gm, '').trim();
  if (tolti.length && (!LETTERA.test(out) || /[:\-–/]\s*$/.test(out))) sospetto = true;
  return { testo: out, tolti, sospetto };
};
// Nel menu il prezzo è spesso l'ultimo numero della riga, senza «€». Si toglie solo da una riga che sembra una voce di
// menu: almeno 3 lettere, numero di 1-3 cifre (o con i decimali), nessuna parola da indirizzo/orario/misura, e il numero
// non attaccato ad altre cifre (telefoni). Le righe dubbie restano com'erano e si contano.
const INDIRIZZO_ORARIO = /\b(?:tel|telefono|cell|cellulare|whatsapp|via|viale|piazza|piazzale|corso|vicolo|strada|largo|cap|orari|orario|aperti|aperto|chiuso|chiusi)\b/i;
// «per 2», «x 4»: porzioni per N persone, non prezzi
const PRIMA_DEL_NUMERO = /^(?:ore|dalle|alle|dal|al|n|nr|civico|anno|anni|tel|cap|per|x)$/i;
const FINE_RIGA_MENU = /^(.*?)([ \t\u00a0\u202f]*[-–:·.…]*[ \t\u00a0\u202f]*(?:€[ \t\u00a0\u202f]*)?(\d{1,3}(?:[.,]\d{1,2})?)[ \t\u00a0\u202f]*(?:€|euro|eur)?)[ \t\u00a0\u202f]*$/i;
const rigaMenu = (riga) => {
  const r = togliPrezzi(riga);
  if (r.tolti.length) return r.sospetto ? { riga, cambiata: false, dubbia: true } : { riga: r.testo, cambiata: true, dubbia: false };
  const m = riga.match(FINE_RIGA_MENU);
  if (!m) return { riga, cambiata: false, dubbia: false };
  const testoVoce = m[1];
  const lettere = (testoVoce.match(/[A-Za-zÀ-ÖØ-öø-ÿ]/g) || []).length;
  if (lettere < 3) return { riga, cambiata: false, dubbia: false };
  const ultima = (testoVoce.trim().split(/[\s(]+/).pop() || '').replace(/[.,:;)]+$/, '');
  // indirizzi, telefoni, orari: il numero finale non è un prezzo. Ogni altra riga dubbia resta com'è ma si conta.
  if (/\d[ \t\u00a0\u202f]*$/.test(testoVoce) || INDIRIZZO_ORARIO.test(riga) || PRIMA_DEL_NUMERO.test(ultima)) {
    return { riga, cambiata: false, dubbia: !INDIRIZZO_ORARIO.test(riga) }; // es. «per 2 18»: resta com'è, ma si segnala
  }
  return { riga: testoVoce.replace(/[ \t\u00a0\u202f]+$/, ''), cambiata: true, dubbia: false };
};
const menuSenzaPrezzi = (t) => {
  const righeMenu = String(t).split(/\r?\n/).map(rigaMenu);
  return { testo: righeMenu.map((x) => x.riga).join('\n'), cambiate: righeMenu.filter((x) => x.cambiata).length, dubbie: righeMenu.filter((x) => x.dubbia).length };
};
const reFrase = (frase, flag) => new RegExp(`(?<![\\p{L}\\d])${frase.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/\s+/g, '\\s+')}(?![\\p{L}\\d])`, flag);
const togliFrase = (t, frase) => String(t).replace(reFrase(frase, 'giu'), '').replace(/[ \t\u00a0\u202f]{2,}/g, ' ').replace(/[ \t\u00a0\u202f]+([,.;:!?)])/g, '$1').replace(/[ \t\u00a0\u202f]+$/gm, '').trim();

// Cosa cambia, da mostrare su Telegram: solo le righe cambiate, con un po' di contesto intorno al pezzo cambiato.
const CONTESTO = 60;
const pezzoCambiato = (sa, sb) => {
  const a = Array.from(sa); const b = Array.from(sb); // per caratteri veri: niente emoji tagliate a metà
  let i = 0;
  while (i < a.length && i < b.length && a[i] === b[i]) i++;
  let j = 0;
  while (j < a.length - i && j < b.length - i && a[a.length - 1 - j] === b[b.length - 1 - j]) j++;
  const pre = a.slice(Math.max(0, i - CONTESTO), i).join('');
  const postA = a.slice(a.length - j, a.length - j + CONTESTO).join('');
  return { pre: (i > CONTESTO ? '…' : '') + pre, tolto: a.slice(i, a.length - j).join(''), messo: b.slice(i, b.length - j).join(''),
    post: postA + (j > CONTESTO ? '…' : '') };
};
const cambi = (prima, dopo) => {
  const ra = String(prima).split(/\r?\n/);
  const rb = String(dopo).split(/\r?\n/);
  const coppie = [];
  if (ra.length === rb.length) ra.forEach((x, k) => { if (x !== rb[k]) coppie.push([x, rb[k]]); });
  else coppie.push([String(prima), String(dopo)]);
  return coppie.map(([a, b]) => pezzoCambiato(a, b));
};
const MAX_PEZZO = 300;
const MAX_CAMBI = 1500;
// la proposta si manda solo se tutto quello che cambia si può far vedere; altrimenti diventa un avviso
const proposta = (p) => {
  const lista = cambi(p.prima, p.dopo);
  const lungo = lista.some((c) => c.tolto.length > MAX_PEZZO || c.messo.length > MAX_PEZZO)
    || lista.reduce((n, c) => n + c.pre.length + c.tolto.length + c.messo.length + c.post.length, 0) > MAX_CAMBI;
  if (lungo || !lista.length) {
    return { ...p, azione: 'avviso', cambi: [], copia_in_menu_con_prezzi: false,
      problema: p.tipo === 'menu'
        ? 'menu_testo ha prezzi non confermati in troppe righe da mostrare con i pulsanti: spostali a mano in menu_con_prezzi'
        : `${p.colonna}: ${p.problema.replace(/\?\s*$/, '')} (troppe modifiche da mostrare con i pulsanti: correggilo a mano)` };
  }
  return { ...p, cambi: lista };
};

// --- dati letti ---
const clientiRighe = $('Leggi Clienti').all().map((i) => i.json || {}).filter((r) => testo(r.cliente));
if (!clientiRighe.length) throw new Error('Revisore fermo: la scheda Clienti è vuota o non si legge. Senza i clienti toglierebbe i prezzi a tutti.');
const clienti = {};
for (const c of clientiRighe) if (!has(clienti, testo(c.cliente))) clienti[testo(c.cliente)] = c; // il 01 prende la prima riga
const perMinuscole = {};
for (const k of Object.keys(clienti)) (perMinuscole[k.toLowerCase()] = perMinuscole[k.toLowerCase()] || []).push(k);
const righe = lette('Leggi Calendario');
const traccia = $('Leggi Revisore').all().map((i) => i.json || {}).filter((r) => testo(r.chiave));
const chiesti = $('Righe e file da guardare').all().map((i) => i.json || {});
const risposte = $('Impronta del file').isExecuted ? $('Impronta del file').all().map((i) => i.json || {}) : [];
const tagliati = Number((chiesti[0] || {}).tagliati) || 0;

// impronte md5 e file non trovati: le risposte di Drive arrivano nello stesso ordine dei file chiesti.
// «Mancante» solo con la risposta 404 o il file nel cestino; ogni altro errore (token scaduto, quota, 5xx) = non controllato.
const codiceErrore = (e) => {
  if (!e || typeof e !== 'object') return String(e || '').match(/\b(\d{3})\b/)?.[1] || '';
  const c = e.httpCode ?? e.statusCode ?? e.status ?? e.code ?? e.cause?.status ?? e.response?.status;
  if (c !== undefined && /^\d{3}$/.test(String(c))) return String(c);
  return String(e.message || e.description || '').match(/\b(4\d\d|5\d\d)\b/)?.[1] || '';
};
const md5DelFile = {};
const fileMancanti = new Set();
let erroriDrive = 0;
chiesti.forEach((c, i) => {
  if (!c.file_id) return;
  const r = risposte[i] || {};
  if (r.error) { if (codiceErrore(r.error) === '404') fileMancanti.add(c.file_id); else erroriDrive++; return; }
  if (r.trashed === true) { fileMancanti.add(c.file_id); return; }
  if (/^[0-9a-f]{32}$/i.test(testo(r.md5Checksum))) md5DelFile[c.file_id] = testo(r.md5Checksum).toLowerCase();
});

// --- righe da guardare in questo giro ---
const conData = righe.map((r) => {
  const d = leggiDataOra(r.data_ora);
  return { r, stato: testo(r.stato).toLowerCase(), d, ms: d && d.ms !== null ? d.ms : null };
});
const nelGiro = conData.filter((x) => {
  if (!VIVI.includes(x.stato)) return false;
  if (orario) return x.ms !== null && x.ms >= adesso && x.ms <= adesso + oreGiro * ORA;
  return x.ms === null || (x.ms >= adesso - ORA && x.ms <= adesso + giorniAvanti * 86400000);
});
const approvatePassate = conData.filter((x) => x.stato === 'approvato' && x.ms !== null && x.ms < adesso - 15 * 60000
  && (!orario || x.ms >= adesso - oreGiro * ORA));
// id ripetuti (anche con spazi diversi) in tutto il Calendario
const quanteVolte = {};
for (const x of conData) { const k = testo(x.r.id); if (k) quanteVolte[k] = (quanteVolte[k] || 0) + 1; }

const problemi = [];
const aggiungi = (p) => {
  p.chiave = [p.tipo, p.chiave_riga, p.colonna, impronta(p.prima), p.sotto || ''].filter((v, k) => k < 4 || v).join('|');
  problemi.push(p);
  return p;
};
const quando = (x) => (x.ms !== null ? oraRoma(x.ms) : testo(x.r.data_ora) || 'senza data');
const baseDi = (x) => {
  const id = testo(x.r.id);
  return { scheda: 'Calendario', chiave_riga: id || `riga ${x.r.row_number}`, id_riga: id, row_number: x.r.row_number,
    cliente: testo(x.r.cliente), quando: quando(x), stato: x.stato };
};
// una riga approvata vicina all'uscita con un problema torna da approvare: una pausa sola per riga, coi motivi in fila
const pausate = {};
const pausaRiga = (x, motivo) => {
  const n = x.r.row_number;
  if (pausate[n]) { pausate[n].problema += `; ${motivo}`; return; }
  pausate[n] = aggiungi({ ...baseDi(x), tipo: 'pausa', azione: 'pausa', colonna: 'stato', prima: testo(x.r.stato), dopo: 'da_approvare',
    solo_stato: true, problema: `torna da approvare perché esce entro ${oreVicina} ore: ${motivo}` });
};

for (const x of nelGiro) {
  const r = x.r;
  const id = testo(r.id);
  const chiaveCliente = testo(r.cliente);
  const base = baseDi(x);

  // id mancante: senza id 04, 01 e il motore non ritrovano la riga
  if (!id) {
    if (!chiaveCliente) continue;
    const pezzo = chiaveCliente.replace(/[^A-Za-z0-9-]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '') || 'cliente';
    const data = x.d ? x.d.chiave.slice(0, 10).replace(/-/g, '') : 'senzadata';
    aggiungi({ ...base, tipo: 'id', azione: 'avviso', colonna: 'id', prima: '', dopo: '',
      problema: `la riga ${r.row_number} non ha l'id: 04, 01 e il motore non la possono lavorare. Scrivi un id unico, per esempio RV-${pezzo}-${data}-${r.row_number}` });
    continue;
  }
  if (quanteVolte[id] > 1) {
    aggiungi({ ...base, tipo: 'id', azione: 'avviso', colonna: 'id', prima: id, dopo: '', sotto: String(r.row_number),
      problema: `l'id «${corto(id, 40)}» è anche in un'altra riga del Calendario: 04 e 01 potrebbero lavorare la riga sbagliata. Dagli un id unico` });
  } else if (String(r.id) !== id) {
    aggiungi({ ...base, tipo: 'id', azione: 'avviso', colonna: 'id', prima: String(r.id), dopo: '',
      problema: `l'id «${corto(id, 40)}» ha degli spazi prima o dopo: toglili, altrimenti 04 e 01 possono non ritrovare la riga` });
  }

  // cliente: deve essere la chiave esatta della scheda Clienti. Se c'è un solo simile, i prezzi si giudicano con quello.
  let cliente = has(clienti, chiaveCliente) ? clienti[chiaveCliente] : null;
  if (!cliente) {
    const simili = perMinuscole[chiaveCliente.toLowerCase()] || [];
    if (simili.length === 1) {
      cliente = clienti[simili[0]];
      aggiungi(proposta({ ...base, tipo: 'formato', azione: 'proposta', colonna: 'cliente', prima: testo(r.cliente), dopo: simili[0],
        problema: `il cliente «${corto(chiaveCliente, 60)}» non è scritto come nella scheda Clienti («${corto(simili[0], 60)}»): 01 e motore non lo ritrovano` }));
    } else {
      aggiungi({ ...base, tipo: 'formato', azione: 'avviso', colonna: 'cliente', prima: testo(r.cliente), dopo: '',
        problema: `il cliente «${corto(chiaveCliente || 'vuoto', 60)}» non c'è nella scheda Clienti: prezzi e frasi di questa riga non li controllo` });
    }
  }

  // data, tipo, piattaforme
  if (x.ms === null) {
    aggiungi({ ...base, tipo: 'formato', azione: 'avviso', colonna: 'data_ora', prima: testo(r.data_ora), dopo: '',
      problema: `data_ora «${corto(testo(r.data_ora) || 'vuota', 40)}» non si legge (o è l'ora saltata dal cambio d'ora): la riga non uscirà` });
  }
  const tipoGrezzo = testo(r.tipo);
  if (TIPI.includes(tipoGrezzo.toLowerCase()) && tipoGrezzo !== tipoGrezzo.toLowerCase()) {
    aggiungi(proposta({ ...base, tipo: 'formato', azione: 'proposta', colonna: 'tipo', prima: tipoGrezzo, dopo: tipoGrezzo.toLowerCase(),
      problema: `tipo «${tipoGrezzo}» con le maiuscole: il motore lo vuole in minuscolo` }));
  } else if (!TIPI.includes(tipoGrezzo.toLowerCase())) {
    aggiungi({ ...base, tipo: 'formato', azione: 'avviso', colonna: 'tipo', prima: tipoGrezzo, dopo: '',
      problema: `tipo «${corto(tipoGrezzo || 'vuoto', 30)}» non valido: usa post, carosello, reel o storia` });
  }
  const piattGrezze = testo(r.piattaforme);
  const voci = piattGrezze.toLowerCase().split(/[+,/ ]+/).filter(Boolean);
  const ig = voci.some((v) => v === 'ig' || v === 'instagram');
  const fb = voci.some((v) => v === 'fb' || v === 'facebook');
  const altre = voci.filter((v) => !['ig', 'instagram', 'fb', 'facebook'].includes(v));
  const normali = ig && fb ? 'ig+fb' : ig ? 'ig' : fb ? 'fb' : '';
  if (!normali || altre.length) {
    aggiungi({ ...base, tipo: 'formato', azione: 'avviso', colonna: 'piattaforme', prima: piattGrezze, dopo: '',
      problema: `piattaforme «${corto(piattGrezze || 'vuote', 30)}» non valide: usa ig, fb oppure ig+fb` });
  } else if (normali !== piattGrezze) {
    aggiungi(proposta({ ...base, tipo: 'formato', azione: 'proposta', colonna: 'piattaforme', prima: piattGrezze, dopo: normali,
      problema: `piattaforme scritte «${corto(piattGrezze, 30)}»: 04 e motore accettano solo ig, fb o ig+fb` }));
  }

  // prezzi non confermati e frasi da verificare, nei testi (solo se il cliente è riconosciuto)
  if (!cliente) continue;
  const prezziOk = siNo(cliente.prezzi_confermati, false);
  const frasi = testo(cliente.da_verificare).split(/[;\n]+/).map((s) => s.trim()).filter((s) => s.length >= 3);
  const approvata = x.stato === 'approvato';
  const vicina = approvata && x.ms !== null && x.ms - adesso <= oreVicina * ORA;
  for (const colonna of COLONNE_TESTO) {
    const valore = testo(r[colonna]);
    if (!valore) continue;
    let attuale = valore; // il testo come sarà dopo le correzioni automatiche: le proposte partono da qui
    if (!prezziOk && PREZZO.test(valore)) {
      const t = togliPrezzi(valore);
      const elenco = corto(t.tolti.join(', '), 80);
      if (!t.sospetto && t.testo) {
        aggiungi({ ...base, tipo: 'prezzo', azione: vicina ? 'pausa' : 'auto', colonna, prima: valore, dopo: t.testo, tolto: t.tolti.join(', '),
          problema: `prezzo non confermato in ${colonna}: tolto «${elenco}»${vicina ? `, e la riga torna da approvare perché esce entro ${oreVicina} ore` : ''}` });
        if (vicina && !pausate[r.row_number]) pausate[r.row_number] = problemi[problemi.length - 1];
        else if (vicina) pausate[r.row_number].problema += `; prezzo tolto anche in ${colonna}`;
        attuale = t.testo;
      } else {
        // toglierlo da solo rovinerebbe la frase: lo sistema una persona. Un'approvata non deve uscire così.
        aggiungi({ ...base, tipo: 'prezzo', azione: 'avviso', colonna, prima: valore, dopo: '', sotto: impronta(elenco),
          problema: `prezzo non confermato in ${colonna} («${elenco}»): toglierlo da solo rovinerebbe la frase, correggilo a mano` });
        if (approvata) {
          const n = r.row_number;
          if (!pausate[n]) {
            pausate[n] = aggiungi({ ...base, tipo: 'pausa', azione: 'pausa', colonna: 'stato', prima: testo(r.stato), dopo: 'da_approvare', solo_stato: true,
              problema: `torna da approvare: in ${colonna} c'è un prezzo non confermato da togliere a mano` });
          } else pausate[n].problema += `; prezzo da togliere a mano in ${colonna}`;
        }
      }
    }
    // tutte le frasi trovate nella stessa colonna in una proposta sola: due proposte sullo stesso testo si escluderebbero
    const trovate = frasi.filter((frase) => reFrase(frase, 'iu').test(attuale));
    if (trovate.length) {
      const dopo = trovate.reduce((t, frase) => togliFrase(t, frase), attuale);
      const elenco = trovate.map((f) => corto(f, 60));
      aggiungi(proposta({ ...base, tipo: 'frase', azione: 'proposta', colonna, prima: attuale, dopo, frase: trovate.join('; '),
        problema: `in ${colonna} ${trovate.length === 1 ? 'c\'è' : 'ci sono'} «${elenco.join('», «')}», da verificare con il titolare: ${trovate.length === 1 ? 'la tolgo' : 'le tolgo'}?` }));
      if (vicina) pausaRiga(x, `in ${colonna} c'è una frase da verificare`);
    }
  }

  // approvato senza file: il 01 la metterebbe in errore
  if (approvata && !fileDellaRiga(r).length) {
    aggiungi({ ...base, tipo: 'senza_media', azione: 'avviso', colonna: 'media', prima: testo(r.media), dopo: '',
      problema: 'approvata ma senza file in media: il 01 non la può pubblicare' });
  }
}

// --- file: stesso file in due righe, stessa impronta, file non trovato (solo righe vive nel giro) ---
const MESE = 30 * 86400000;
const viviEPubblicati = conData.filter((x) => VIVI.includes(x.stato) || (x.stato === 'pubblicato' && x.ms !== null && x.ms >= adesso - MESE));
const righeDelFile = {};
const righeDellImpronta = {};
for (const x of viviEPubblicati) {
  for (const f of new Set(fileDellaRiga(x.r))) {
    (righeDelFile[f] = righeDelFile[f] || []).push(x);
    if (md5DelFile[f]) (righeDellImpronta[md5DelFile[f]] = righeDellImpronta[md5DelFile[f]] || []).push({ x, f });
  }
}
const ordine = (a, b) => (a.ms ?? Infinity) - (b.ms ?? Infinity) || a.r.row_number - b.r.row_number;
const segnalaFile = (x, problema, sotto, colonna = 'media') => {
  if (!testo(x.r.id)) return;
  const base = baseDi(x);
  if (x.stato === 'approvato') {
    const vicina = x.ms !== null && x.ms - adesso <= oreVicina * ORA;
    if (vicina) { pausaRiga(x, problema); return; }
    if (pausate[x.r.row_number]) { pausate[x.r.row_number].problema += `; ${problema}`; return; } // torna già da approvare
    aggiungi(proposta({ ...base, tipo: 'file', azione: 'proposta', colonna: 'stato', prima: testo(x.r.stato), dopo: 'da_approvare', sotto,
      problema: `${problema}: la rimetto da approvare?` }));
  } else {
    aggiungi({ ...base, tipo: 'file', azione: 'avviso', colonna, prima: testo(x.r[colonna]), dopo: '', sotto, problema });
  }
};
const inGiro = new Set(nelGiro.map((x) => x.r.row_number));
for (const [f, gruppo] of Object.entries(righeDelFile)) {
  if (gruppo.length < 2) continue;
  const ord = [...gruppo].sort(ordine);
  for (const x of ord.slice(1)) {
    if (!inGiro.has(x.r.row_number) || x.stato === 'pubblicato') continue;
    segnalaFile(x, `lo stesso file è anche nella riga ${corto(testo(ord[0].r.id) || ord[0].r.row_number, 40)}: uscirebbe due volte`, `doppio:${f}`);
  }
}
for (const gruppo of Object.values(righeDellImpronta)) {
  const fileDiversi = new Set(gruppo.map((g) => g.f));
  if (fileDiversi.size < 2) continue;
  const ord = [...gruppo].sort((a, b) => ordine(a.x, b.x));
  const primo = ord[0];
  for (const g of ord.slice(1)) {
    if (g.f === primo.f || !inGiro.has(g.x.r.row_number) || g.x.stato === 'pubblicato') continue;
    segnalaFile(g.x, `ha la stessa foto (stesso contenuto, file diverso) della riga ${corto(testo(primo.x.r.id) || primo.x.r.row_number, 40)}`, `impronta:${g.f}`);
  }
}
for (const x of nelGiro) {
  const mancanti = fileDellaRiga(x.r).filter((f) => fileMancanti.has(f));
  if (mancanti.length) segnalaFile(x, `${mancanti.length === 1 ? 'un file' : mancanti.length + ' file'} di media o copertina non si trova più su Drive (cancellato)`, `mancante:${mancanti.join(',')}`);
}

// --- approvate con la data passata: il 01 è fermo? ---
for (const x of approvatePassate) {
  aggiungi({ ...baseDi(x), tipo: 'passato', azione: 'avviso', colonna: 'stato', prima: 'approvato', dopo: '',
    problema: `approvata per le ${quando(x)} ma non ancora pubblicata: il 01 è acceso?` });
}

// --- menu con prezzi e prezzi non confermati (solo nel giro delle 8:40) ---
if (!orario) {
  for (const [chiave, c] of Object.entries(clienti)) {
    if (!siNo(c.attivo, false) || siNo(c.prezzi_confermati, false)) continue;
    const menu = testo(c.menu_testo);
    if (!menu) continue;
    const pulito = menuSenzaPrezzi(menu);
    const restaPrezzo = PREZZO.test(pulito.testo);
    if (!pulito.cambiate && !restaPrezzo) continue;
    const base = { scheda: 'Clienti', chiave_riga: chiave, id_riga: '', row_number: c.row_number, cliente: chiave, quando: '', stato: '', tipo: 'menu', colonna: 'menu_testo' };
    if (!pulito.cambiate) {
      aggiungi({ ...base, azione: 'avviso', prima: menu, dopo: '',
        problema: 'menu_testo ha dei prezzi non confermati che non riesco a togliere senza rovinare le righe: spostali a mano in menu_con_prezzi' });
      continue;
    }
    const vuota = !testo(c.menu_con_prezzi);
    const resto = restaPrezzo || pulito.dubbie ? ` Attenzione: ${pulito.dubbie || 'alcune'} righe dubbie restano come sono, guardale a mano.` : '';
    aggiungi(proposta({ ...base, azione: 'proposta', prima: menu, dopo: pulito.testo, copia_in_menu_con_prezzi: vuota,
      problema: (vuota
        ? `menu_testo ha i prezzi non confermati in ${pulito.cambiate} righe: copio il menu com'è in menu_con_prezzi e tolgo i prezzi da menu_testo?`
        : `menu_testo ha i prezzi non confermati in ${pulito.cambiate} righe: li tolgo? (menu_con_prezzi è già pieno e non lo tocco)`) + resto }));
  }
}

// --- doppioni con la traccia: deciso = non torna; proposto o avvisato nelle ultime ore = non torna ---
const tracciaPerChiave = {};
for (const t of traccia) (tracciaPerChiave[testo(t.chiave)] = tracciaPerChiave[testo(t.chiave)] || []).push(t);
// un'ora in più dell'attesa dei pulsanti: il messaggio di ieri deve essere già chiuso quando arriva quello nuovo
// proposte: finestra uguale all'attesa (il messaggio con i pulsanti si chiude un'ora prima); avvisi: 20 ore, così il giro
// delle 8:40 del giorno dopo li ripete
const recente = (t, ore) => { const d = leggiDataOra(t.data_ora); return d && d.ms !== null && adesso - d.ms < ore * ORA; };
let saltati = 0;
const finali = [];
for (const p of problemi) {
  p.problema = corto(p.problema, 300);
  if (p.azione === 'proposta' || p.azione === 'avviso') {
    const prec = tracciaPerChiave[p.chiave] || [];
    const deciso = prec.some((t) => /^(applicato|ignorato)\b/.test(testo(t.esito).toLowerCase()));
    const giaDetto = prec.some((t) => (/^proposto\b/.test(testo(t.esito).toLowerCase()) && recente(t, oreAttesa))
      || (/^avvisato\b/.test(testo(t.esito).toLowerCase()) && recente(t, 20)));
    if (deciso || giaDetto) { saltati++; continue; }
  }
  finali.push(p);
}
// stesso problema due volte nello stesso giro: uno solo
const visti = new Set();
const unici = finali.filter((p) => (visti.has(p.chiave) ? false : visti.add(p.chiave)));
let proposte = 0;
let oltre = 0;
const tenuti = unici.filter((p) => {
  if (p.azione !== 'proposta') return true;
  if (proposte < maxProposte) { proposte++; return true; }
  oltre++;
  return false;
});

return [{
  json: {
    giro: orario ? 'orario' : 'giornaliero',
    problemi: tenuti,
    correzioni: tenuti.filter((p) => p.azione === 'auto' || p.azione === 'pausa').length,
    proposte,
    avvisi: tenuti.filter((p) => p.azione === 'avviso').length,
    saltati_doppi: saltati,
    proposte_oltre_limite: oltre,
    impronte_non_controllate: tagliati,
    drive_non_risponde: erroriDrive,
  },
}];

// ── Funzioni comuni del Revisore (copiate in testa a ogni nodo Code dal costruttore) ──
const testo = (v) => (v === null || v === undefined ? '' : String(v)).trim();
const due = (n) => String(n).padStart(2, '0');
const has = (o, k) => Object.prototype.hasOwnProperty.call(o || {}, k);
const corto = (s, n) => { const c = Array.from(String(s ?? '')); return c.length > n ? c.slice(0, n - 1).join('') + '…' : String(s ?? ''); };
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Telegram con i pulsanti (sendAndWait) usa sempre il Markdown semplice: si neutralizzano _ * ` [
const md = (v) => String(v ?? '').replace(/\\/g, '/').replace(/([_*`[])/g, '\\$1');
const siNo = (v, seVuoto) => { const t = testo(v).toLowerCase(); if (!t) return seVuoto; return ['si', 'sì', 'yes', 'true', 'vero', '1', 'x', 'ok'].includes(t); };
const lette = (nodo) => $(nodo).all().map((i) => i.json || {}).filter((r) => has(r, 'row_number')); // solo righe vere del foglio
const partiRoma = (ms) => {
  const p = {};
  for (const x of new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(ms))) p[x.type] = x.value;
  return { anno: Number(p.year), mese: Number(p.month), giorno: Number(p.day), ore: Number(p.hour), minuti: Number(p.minute) };
};
const romaMs = (a, me, g, o, mi) => {
  const base = Date.UTC(a, me - 1, g, o, mi);
  for (const off of [60, 120]) { const t = base - off * 60000; const p = partiRoma(t); if (p.anno === a && p.mese === me && p.giorno === g && p.ore === o && p.minuti === mi) return t; }
  return null;
};
const oraRoma = (ms) => { const p = partiRoma(ms); return `${p.anno}-${due(p.mese)}-${due(p.giorno)} ${due(p.ore)}:${due(p.minuti)}`; };
const giorniNelMese = (a, me) => new Date(Date.UTC(a, me, 0)).getUTCDate();
// data_ora come la legge il 04: testo AAAA-MM-GG HH:MM, GG/MM/AAAA HH:MM, oppure numero di Sheets
const leggiDataOra = (v) => {
  let a; let me; let g; let o; let mi;
  if (typeof v === 'number' && isFinite(v)) {
    const t = new Date(Date.UTC(1899, 11, 30) + Math.round(v * 1440) * 60000);
    [a, me, g, o, mi] = [t.getUTCFullYear(), t.getUTCMonth() + 1, t.getUTCDate(), t.getUTCHours(), t.getUTCMinutes()];
  } else {
    const s = testo(v).replace(/\s+/g, ' ');
    let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2})[:.](\d{2})/);
