  : esito === 'ignorato' && testo(d.modalita) !== 'vero' ? `🧪 Revisore in prova: hai premuto Ignora (${dove}). Niente scritto.`
  : esito === 'ignorato' ? `👌 Revisore: lasciato com'è (${dove}). Non te lo ripropongo.`
  : esito === 'errore telegram' ? `⚠️ Revisore: la proposta per ${dove} non è arrivata (Telegram non ha accettato il messaggio). La ripropongo domani.`
  : '';
return [{ json: { ...riga, conferma, chat_id: d.chat_id, sheet_id: d.sheet_id, scheda_revisore: d.scheda_revisore } }];
